class Solution {
public:
    vector<string> createGrid(int k) {
        vector<string> a(21, string(25, '#'));
        for (int r=0;r<21;++r) a[r][24]='.';
        for (int bit=0;bit<10;++bit) {
            int r=2*bit, c=2*bit;
            for (int i=r;i<=r+1;++i)
                for (int j=c;j<=c+1;++j) a[i][j]='.';
            if (bit<9) {
                a[r+2][c+1]='.';
                a[r+2][c+2]='.';
            }
            if (k & (1<<bit))
                for (int j=c+1;j<25;++j) a[r][j]='.';
        }
        return a;
    }
};
